-- Phase 8 portable state checkpoint.
-- Runtime SQLite is generated by scripts/record_phase8_ledger.py after the acceptance exam.
BEGIN;
CREATE TABLE IF NOT EXISTS phase8_security_controls (control_id TEXT PRIMARY KEY,status TEXT NOT NULL,evidence TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS phase8_tasks (task TEXT PRIMARY KEY,status TEXT NOT NULL,evidence TEXT NOT NULL);
COMMIT;
